sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-23: defaults from reservation, validation and due date (D-16, D-19)
    var isInsert = current.operation() == 'insert';
    var res = current.reservation.getRefRecord();
    var errors = [];

    if (res.isValidRecord()) {
        if (current.vehicle.nil() || current.reservation.changes()) {
            current.setValue('vehicle', res.getValue('assigned_vehicle'));
        }
        if (current.driver.nil()) {
            current.setValue('driver', res.getValue('assigned_driver') || res.getValue('requested_by'));
        }
        // violation_date must fall inside the reservation period
        if (!current.violation_date.nil() && !res.start_datetime.nil() && !res.end_datetime.nil()) {
            var vd = current.getValue('violation_date');
            var from = new GlideDateTime(res.getValue('start_datetime')).getLocalDate().getValue();
            var to = new GlideDateTime(res.getValue('end_datetime')).getLocalDate().getValue();
            if (vd < from || vd > to) {
                errors.push('Violation Date must fall inside the reservation period (' + from + ' to ' + to + ').');
            }
        }
    }

    var amount = parseFloat(current.getValue('amount'));
    if (isNaN(amount) || amount <= 0) {
        errors.push('Amount must be greater than 0.');
    }

    if (errors.length) {
        for (var i = 0; i < errors.length; i++) {
            gs.addErrorMessage(errors[i]);
        }
        current.setAbortAction(true);
        return;
    }

    if (current.getValue('paid_by') == 'DRIVER' && current.reimbursement_status.nil()) {
        current.setValue('reimbursement_status', 'PENDING');
    }

    // D-19: due_date = violation_date + violation.escalation_days (property read when the date is set,
    // so a property change only affects new violations)
    if (!current.violation_date.nil() && (isInsert || current.violation_date.changes() || current.due_date.nil())) {
        var days = parseInt(gs.getProperty('x_1850693_enterp_0.violation.escalation_days', '30'), 10);
        var due = new GlideDate();
        due.setValue(current.getValue('violation_date'));
        due.addDaysUTC(isNaN(days) ? 30 : days);
        current.setValue('due_date', due.getValue());
    }
})(current, previous);
